import json

def diff(a, b):
    out = []
    _walk(a, b, "$", out)
    return sorted(out)

def _same_kind(v):
    return isinstance(v, dict) or isinstance(v, list)

def _walk(a, b, path, out):
    if isinstance(a, dict) and isinstance(b, dict):
        for k in sorted(set(a) | set(b)):
            child = path + "." + k
            if k not in a:
                out.append(f"+ {child}: {json.dumps(b[k], sort_keys=True)}")
            elif k not in b:
                out.append(f"- {child}: {json.dumps(a[k], sort_keys=True)}")
            else:
                _walk(a[k], b[k], child, out)
        return
    if isinstance(a, list) and isinstance(b, list):
        n = max(len(a), len(b))
        for i in range(n):
            child = f"{path}[{i}]"
            if i >= len(a):
                out.append(f"+ {child}: {json.dumps(b[i], sort_keys=True)}")
            elif i >= len(b):
                out.append(f"- {child}: {json.dumps(a[i], sort_keys=True)}")
            else:
                _walk(a[i], b[i], child, out)
        return
    if type(a) is type(b) and a == b:
        return
    out.append(f"~ {path}: {json.dumps(a, sort_keys=True)} -> {json.dumps(b, sort_keys=True)}")
```

